FFStatus OrderCancelReplaceRequest::toString(falconfix::FastBuffer &out, bool includeMilliseconds) const noexcept {
	static constexpr std::string_view HDR = "8=FIX4.2\x01""9=000000\x01""35=G\x01";
	static constexpr std::size_t HDR_BL_POS = 11;
	static constexpr std::size_t HDR_CALC_OFFSET = 18;

	out.clear();
	if (!out.reserve_noexcept(compute_buffer_size())) [[unlikely]] {
		return FF_SYS_ERR(BAD_ALLOC);
	}

	char *p = out.data();
	std::memcpy(p, HDR.data(), HDR.size());
	p += HDR.size();
	if ((p = m_Header.encode(p, includeMilliseconds)) == nullptr) {
		return FF_FIX_VALIDATION_ERR(COMPONENT_VALIDATION_FAILED, field_id::BeginString);
	}

	if (hasOrderID()) { WRITE_TAG3(fix42::tag_const::OrderID); std::memcpy(p, m_OrderID.data(), m_OrderID.size()); p += m_OrderID.size(); *p++ = fix42::serialize::SOH; }
	if (hasClientID()) { WRITE_TAG4(fix42::tag_const::ClientID); std::memcpy(p, m_ClientID.data(), m_ClientID.size()); p += m_ClientID.size(); *p++ = fix42::serialize::SOH; }
	if (hasExecBroker()) { WRITE_TAG3(fix42::tag_const::ExecBroker); std::memcpy(p, m_ExecBroker.data(), m_ExecBroker.size()); p += m_ExecBroker.size(); *p++ = fix42::serialize::SOH; }
	if (hasOrigClOrdID()) { WRITE_TAG3(fix42::tag_const::OrigClOrdID); std::memcpy(p, m_OrigClOrdID.data(), m_OrigClOrdID.size()); p += m_OrigClOrdID.size(); *p++ = fix42::serialize::SOH; }
	if (hasClOrdID()) { WRITE_TAG3(fix42::tag_const::ClOrdID); std::memcpy(p, m_ClOrdID.data(), m_ClOrdID.size()); p += m_ClOrdID.size(); *p++ = fix42::serialize::SOH; }
	if (hasListID()) { WRITE_TAG3(fix42::tag_const::ListID); std::memcpy(p, m_ListID.data(), m_ListID.size()); p += m_ListID.size(); *p++ = fix42::serialize::SOH; }
	if (hasAccount()) { WRITE_TAG2(fix42::tag_const::Account); std::memcpy(p, m_Account.data(), m_Account.size()); p += m_Account.size(); *p++ = fix42::serialize::SOH; }
	if (!m_NoAllocsGroup.empty()) {
		WRITE_TAG3(fix42::tag_const::NoAllocs);
		p += falconfix::itoa(static_cast<int64_t>(m_NoAllocsGroup.size()), p);
		*p++ = fix42::serialize::SOH;
		for (const auto &entry : m_NoAllocsGroup) {
			p = entry.encode(p, includeMilliseconds);
		}
	}
	if (hasSettlmntTyp()) { WRITE_TAG3(fix42::tag_const::SettlmntTyp); *p++ = m_SettlmntTyp; *p++ = fix42::serialize::SOH; }
	if (hasFutSettDate()) { WRITE_TAG3(fix42::tag_const::FutSettDate); p += fix42::datetime::format_UTCDateOnly(m_FutSettDate, p); *p++ = fix42::serialize::SOH; }
	if (hasHandlInst()) { WRITE_TAG3(fix42::tag_const::HandlInst); *p++ = m_HandlInst; *p++ = fix42::serialize::SOH; }
	if (hasExecInst()) { WRITE_TAG3(fix42::tag_const::ExecInst); std::memcpy(p, m_ExecInst.data(), m_ExecInst.size()); p += m_ExecInst.size(); *p++ = fix42::serialize::SOH; }
	if (hasMinQty()) { WRITE_TAG4(fix42::tag_const::MinQty); p += falconfix::dtoa(m_MinQty, p); *p++ = fix42::serialize::SOH; }
	if (hasMaxFloor()) { WRITE_TAG4(fix42::tag_const::MaxFloor); p += falconfix::dtoa(m_MaxFloor, p); *p++ = fix42::serialize::SOH; }
	if (hasExDestination()) { WRITE_TAG4(fix42::tag_const::ExDestination); std::memcpy(p, m_ExDestination.data(), m_ExDestination.size()); p += m_ExDestination.size(); *p++ = fix42::serialize::SOH; }
	if (!m_NoTradingSessionsGroup.empty()) {
		WRITE_TAG4(fix42::tag_const::NoTradingSessions);
		p += falconfix::itoa(static_cast<int64_t>(m_NoTradingSessionsGroup.size()), p);
		*p++ = fix42::serialize::SOH;
		for (const auto &entry : m_NoTradingSessionsGroup) {
			p = entry.encode(p, includeMilliseconds);
		}
	}
	if (hasSymbol()) { WRITE_TAG3(fix42::tag_const::Symbol); std::memcpy(p, m_Symbol.data(), m_Symbol.size()); p += m_Symbol.size(); *p++ = fix42::serialize::SOH; }
	if (hasSymbolSfx()) { WRITE_TAG3(fix42::tag_const::SymbolSfx); std::memcpy(p, m_SymbolSfx.data(), m_SymbolSfx.size()); p += m_SymbolSfx.size(); *p++ = fix42::serialize::SOH; }
	if (hasSecurityID()) { WRITE_TAG3(fix42::tag_const::SecurityID); std::memcpy(p, m_SecurityID.data(), m_SecurityID.size()); p += m_SecurityID.size(); *p++ = fix42::serialize::SOH; }
	if (hasIDSource()) { WRITE_TAG3(fix42::tag_const::IDSource); std::memcpy(p, m_IDSource.data(), m_IDSource.size()); p += m_IDSource.size(); *p++ = fix42::serialize::SOH; }
	if (hasSecurityType()) { WRITE_TAG4(fix42::tag_const::SecurityType); std::memcpy(p, m_SecurityType.data(), m_SecurityType.size()); p += m_SecurityType.size(); *p++ = fix42::serialize::SOH; }
	if (hasMaturityMonthYear()) { WRITE_TAG4(fix42::tag_const::MaturityMonthYear); std::memcpy(p, m_MaturityMonthYear.data(), m_MaturityMonthYear.size()); p += m_MaturityMonthYear.size(); *p++ = fix42::serialize::SOH; }
	if (hasMaturityDay()) { WRITE_TAG4(fix42::tag_const::MaturityDay); p += falconfix::itoa(m_MaturityDay, p); *p++ = fix42::serialize::SOH; }
	if (hasPutOrCall()) { WRITE_TAG4(fix42::tag_const::PutOrCall); p += falconfix::itoa(m_PutOrCall, p); *p++ = fix42::serialize::SOH; }
	if (hasStrikePrice()) { WRITE_TAG4(fix42::tag_const::StrikePrice); p += falconfix::dtoa(m_StrikePrice, p); *p++ = fix42::serialize::SOH; }
	if (hasOptAttribute()) { WRITE_TAG4(fix42::tag_const::OptAttribute); *p++ = m_OptAttribute; *p++ = fix42::serialize::SOH; }
	if (hasContractMultiplier()) { WRITE_TAG4(fix42::tag_const::ContractMultiplier); p += falconfix::dtoa(m_ContractMultiplier, p); *p++ = fix42::serialize::SOH; }
	if (hasCouponRate()) { WRITE_TAG4(fix42::tag_const::CouponRate); p += falconfix::dtoa(m_CouponRate, p); *p++ = fix42::serialize::SOH; }
	if (hasSecurityExchange()) { WRITE_TAG4(fix42::tag_const::SecurityExchange); std::memcpy(p, m_SecurityExchange.data(), m_SecurityExchange.size()); p += m_SecurityExchange.size(); *p++ = fix42::serialize::SOH; }
	if (hasIssuer()) { WRITE_TAG4(fix42::tag_const::Issuer); std::memcpy(p, m_Issuer.data(), m_Issuer.size()); p += m_Issuer.size(); *p++ = fix42::serialize::SOH; }
	if (hasEncodedIssuerLen()) { WRITE_TAG4(fix42::tag_const::EncodedIssuerLen); p += falconfix::itoa(m_EncodedIssuerLen, p); *p++ = fix42::serialize::SOH; }
	if (hasEncodedIssuer()) { WRITE_TAG4(fix42::tag_const::EncodedIssuer); std::memcpy(p, m_EncodedIssuer.data(), m_EncodedIssuer.size()); p += m_EncodedIssuer.size(); *p++ = fix42::serialize::SOH; }
	if (hasSecurityDesc()) { WRITE_TAG4(fix42::tag_const::SecurityDesc); std::memcpy(p, m_SecurityDesc.data(), m_SecurityDesc.size()); p += m_SecurityDesc.size(); *p++ = fix42::serialize::SOH; }
	if (hasEncodedSecurityDescLen()) { WRITE_TAG4(fix42::tag_const::EncodedSecurityDescLen); p += falconfix::itoa(m_EncodedSecurityDescLen, p); *p++ = fix42::serialize::SOH; }
	if (hasEncodedSecurityDesc()) { WRITE_TAG4(fix42::tag_const::EncodedSecurityDesc); std::memcpy(p, m_EncodedSecurityDesc.data(), m_EncodedSecurityDesc.size()); p += m_EncodedSecurityDesc.size(); *p++ = fix42::serialize::SOH; }
	if (hasSide()) { WRITE_TAG3(fix42::tag_const::Side); *p++ = m_Side; *p++ = fix42::serialize::SOH; }
	if (hasTransactTime()) { WRITE_TAG3(fix42::tag_const::TransactTime); p += fix42::datetime::format_UTCTimestamp_compact(m_TransactTime, p, includeMilliseconds); *p++ = fix42::serialize::SOH; }
	if (hasOrderQty()) { WRITE_TAG3(fix42::tag_const::OrderQty); p += falconfix::dtoa(m_OrderQty, p); *p++ = fix42::serialize::SOH; }
	if (hasCashOrderQty()) { WRITE_TAG4(fix42::tag_const::CashOrderQty); p += falconfix::dtoa(m_CashOrderQty, p); *p++ = fix42::serialize::SOH; }
	if (hasOrdType()) { WRITE_TAG3(fix42::tag_const::OrdType); *p++ = m_OrdType; *p++ = fix42::serialize::SOH; }
	if (hasPrice()) { WRITE_TAG3(fix42::tag_const::Price); p += falconfix::dtoa(m_Price, p); *p++ = fix42::serialize::SOH; }
	if (hasStopPx()) { WRITE_TAG3(fix42::tag_const::StopPx); p += falconfix::dtoa(m_StopPx, p); *p++ = fix42::serialize::SOH; }
	if (hasPegDifference()) { WRITE_TAG4(fix42::tag_const::PegDifference); p += falconfix::dtoa(m_PegDifference, p); *p++ = fix42::serialize::SOH; }
	if (hasDiscretionInst()) { WRITE_TAG4(fix42::tag_const::DiscretionInst); *p++ = m_DiscretionInst; *p++ = fix42::serialize::SOH; }
	if (hasDiscretionOffset()) { WRITE_TAG4(fix42::tag_const::DiscretionOffset); p += falconfix::dtoa(m_DiscretionOffset, p); *p++ = fix42::serialize::SOH; }
	if (hasComplianceID()) { WRITE_TAG4(fix42::tag_const::ComplianceID); std::memcpy(p, m_ComplianceID.data(), m_ComplianceID.size()); p += m_ComplianceID.size(); *p++ = fix42::serialize::SOH; }
	if (hasSolicitedFlag()) { WRITE_TAG4(fix42::tag_const::SolicitedFlag); *p++ = m_SolicitedFlag ? 'Y' : 'N'; *p++ = fix42::serialize::SOH; }
	if (hasCurrency()) { WRITE_TAG3(fix42::tag_const::Currency); std::memcpy(p, m_Currency.data(), m_Currency.size()); p += m_Currency.size(); *p++ = fix42::serialize::SOH; }
	if (hasTimeInForce()) { WRITE_TAG3(fix42::tag_const::TimeInForce); *p++ = m_TimeInForce; *p++ = fix42::serialize::SOH; }
	if (hasEffectiveTime()) { WRITE_TAG4(fix42::tag_const::EffectiveTime); p += fix42::datetime::format_UTCTimestamp_compact(m_EffectiveTime, p, includeMilliseconds); *p++ = fix42::serialize::SOH; }
	if (hasExpireDate()) { WRITE_TAG4(fix42::tag_const::ExpireDate); p += fix42::datetime::format_UTCDateOnly(m_ExpireDate, p); *p++ = fix42::serialize::SOH; }
	if (hasExpireTime()) { WRITE_TAG4(fix42::tag_const::ExpireTime); p += fix42::datetime::format_UTCTimestamp_compact(m_ExpireTime, p, includeMilliseconds); *p++ = fix42::serialize::SOH; }
	if (hasGTBookingInst()) { WRITE_TAG4(fix42::tag_const::GTBookingInst); p += falconfix::itoa(m_GTBookingInst, p); *p++ = fix42::serialize::SOH; }
	if (hasCommission()) { WRITE_TAG3(fix42::tag_const::Commission); p += falconfix::dtoa(m_Commission, p); *p++ = fix42::serialize::SOH; }
	if (hasCommType()) { WRITE_TAG3(fix42::tag_const::CommType); *p++ = m_CommType; *p++ = fix42::serialize::SOH; }
	if (hasRule80A()) { WRITE_TAG3(fix42::tag_const::Rule80A); *p++ = m_Rule80A; *p++ = fix42::serialize::SOH; }
	if (hasForexReq()) { WRITE_TAG4(fix42::tag_const::ForexReq); *p++ = m_ForexReq ? 'Y' : 'N'; *p++ = fix42::serialize::SOH; }
	if (hasSettlCurrency()) { WRITE_TAG4(fix42::tag_const::SettlCurrency); std::memcpy(p, m_SettlCurrency.data(), m_SettlCurrency.size()); p += m_SettlCurrency.size(); *p++ = fix42::serialize::SOH; }
	if (hasText()) { WRITE_TAG3(fix42::tag_const::Text); std::memcpy(p, m_Text.data(), m_Text.size()); p += m_Text.size(); *p++ = fix42::serialize::SOH; }
	if (hasEncodedTextLen()) { WRITE_TAG4(fix42::tag_const::EncodedTextLen); p += falconfix::itoa(m_EncodedTextLen, p); *p++ = fix42::serialize::SOH; }
	if (hasEncodedText()) { WRITE_TAG4(fix42::tag_const::EncodedText); std::memcpy(p, m_EncodedText.data(), m_EncodedText.size()); p += m_EncodedText.size(); *p++ = fix42::serialize::SOH; }
	if (hasFutSettDate2()) { WRITE_TAG4(fix42::tag_const::FutSettDate2); p += fix42::datetime::format_UTCDateOnly(m_FutSettDate2, p); *p++ = fix42::serialize::SOH; }
	if (hasOrderQty2()) { WRITE_TAG4(fix42::tag_const::OrderQty2); p += falconfix::dtoa(m_OrderQty2, p); *p++ = fix42::serialize::SOH; }
	if (hasOpenClose()) { WRITE_TAG3(fix42::tag_const::OpenClose); *p++ = m_OpenClose; *p++ = fix42::serialize::SOH; }
	if (hasCoveredOrUncovered()) { WRITE_TAG4(fix42::tag_const::CoveredOrUncovered); p += falconfix::itoa(m_CoveredOrUncovered, p); *p++ = fix42::serialize::SOH; }
	if (hasCustomerOrFirm()) { WRITE_TAG4(fix42::tag_const::CustomerOrFirm); p += falconfix::itoa(m_CustomerOrFirm, p); *p++ = fix42::serialize::SOH; }
	if (hasMaxShow()) { WRITE_TAG4(fix42::tag_const::MaxShow); p += falconfix::dtoa(m_MaxShow, p); *p++ = fix42::serialize::SOH; }
	if (hasLocateReqd()) { WRITE_TAG4(fix42::tag_const::LocateReqd); *p++ = m_LocateReqd ? 'Y' : 'N'; *p++ = fix42::serialize::SOH; }
	if (hasClearingFirm()) { WRITE_TAG4(fix42::tag_const::ClearingFirm); std::memcpy(p, m_ClearingFirm.data(), m_ClearingFirm.size()); p += m_ClearingFirm.size(); *p++ = fix42::serialize::SOH; }
	if (hasClearingAccount()) { WRITE_TAG4(fix42::tag_const::ClearingAccount); std::memcpy(p, m_ClearingAccount.data(), m_ClearingAccount.size()); p += m_ClearingAccount.size(); *p++ = fix42::serialize::SOH; }

	if ((p = m_Trailer.encode(p, includeMilliseconds)) == nullptr) {
		return FF_FIX_VALIDATION_ERR(COMPONENT_VALIDATION_FAILED, field_id::SignatureLength);
	}

	const std::size_t msg_len_no_checksum = static_cast<std::size_t>(p - out.data());
	const std::size_t body_len = msg_len_no_checksum - HDR_CALC_OFFSET;

	char *digits = out.data() + HDR_BL_POS;
	digits[0] = '0' + ((body_len / 100000) % 10);
	digits[1] = '0' + ((body_len / 10000 ) % 10);
	digits[2] = '0' + ((body_len / 1000  ) % 10);
	digits[3] = '0' + ((body_len / 100   ) % 10);
	digits[4] = '0' + ((body_len / 10    ) % 10);
	digits[5] = '0' +  (body_len           % 10);

	std::uint32_t cksum = 0;
	for (const char *it = out.data(); it != out.data() + msg_len_no_checksum; ++it) {
		cksum += static_cast<unsigned char>(*it);
	}
	cksum &= 0xFF;

	*p++ = '1'; *p++ = '0'; *p++ = '=';
	*p++ = char('0' + (cksum / 100));
	*p++ = char('0' + ((cksum / 10) % 10));
	*p++ = char('0' + (cksum % 10));
	*p++ = fix42::serialize::SOH;
	out.commit(static_cast<std::size_t>(p - out.data()));
	return FF_OK();
}

